targets.clientTransformScript:
javascript(/**
 * @param {params} params
 * @param {api} params.api
 * @param {any} params.event
 */
function evaluateEvent({
    api,
    event
}) {
    const id = event.payload.item.id;
    return {
        propName: "filterFeatureVal",
        value: id === "All" ? [] : [event.payload.item]
    };
})

